using System;using System.Linq;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;
public static class StationDistanceLodBuilder {
 const string Root="Assets/Optimization/StationDistanceLODs";const string Work="Recovery/StationDistanceLODs_20261107";
 static string Key(Mesh mesh){string guid;long id;AssetDatabase.TryGetGUIDAndLocalFileIdentifier(mesh,out guid,out id);return guid+"_"+id;}
 static Mesh Load(Mesh original,string level){string key=Key(original),path=Root+"/"+key+"_"+level+".asset";var found=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(found)return found;using(var reader=new BinaryReader(File.OpenRead(Work+"/"+key+"_"+level+".output"))){int nv=reader.ReadInt32(),nf=reader.ReadInt32();if(nv<3||nf<1||nv>2000000||nf>2000000)throw new Exception("Invalid mesh header");var v=new Vector3[nv];var n=new Vector3[nv];var uv=new Vector2[nv];for(int i=0;i<nv;i++){v[i]=new Vector3(reader.ReadSingle(),reader.ReadSingle(),reader.ReadSingle());n[i]=new Vector3(reader.ReadSingle(),reader.ReadSingle(),reader.ReadSingle());uv[i]=new Vector2(reader.ReadSingle(),reader.ReadSingle());}var sub=new List<int>[original.subMeshCount];for(int i=0;i<sub.Length;i++)sub[i]=new List<int>();for(int f=0;f<nf;f++){int a=reader.ReadInt32(),b=reader.ReadInt32(),c=reader.ReadInt32(),s=reader.ReadInt32();if(a<0||b<0||c<0||a>=nv||b>=nv||c>=nv||s<0||s>=sub.Length)throw new Exception("Invalid mesh indices");sub[s].AddRange(new[]{a,b,c});}var mesh=new Mesh{name=original.name+"_"+key.Substring(0,6)+"_"+level,indexFormat=nv>65535?IndexFormat.UInt32:IndexFormat.UInt16};mesh.vertices=v;mesh.normals=n;mesh.uv=uv;mesh.subMeshCount=sub.Length;for(int i=0;i<sub.Length;i++)mesh.SetTriangles(sub[i],i,false);mesh.RecalculateBounds();float error=((mesh.bounds.min-original.bounds.min).magnitude+(mesh.bounds.max-original.bounds.max).magnitude)/Mathf.Max(.000001f,original.bounds.size.magnitude);if(error>.08f)throw new Exception("Bounds mismatch "+key+" "+level+" ratio="+error);mesh.RecalculateTangents();mesh.bounds=original.bounds;AssetDatabase.CreateAsset(mesh,path);return mesh;}}
 static string PhysicsSnapshot()=>string.Join("\n",UnityEngine.Object.FindObjectsByType<Collider>(FindObjectsInactive.Include,FindObjectsSortMode.None).OrderBy(c=>GlobalObjectId.GetGlobalObjectIdSlow(c).ToString()).Select(c=>GlobalObjectId.GetGlobalObjectIdSlow(c)+EditorJsonUtility.ToJson(c)));
 static MeshRenderer Child(MeshRenderer source,Mesh mesh,string label){var go=new GameObject(label);Undo.RegisterCreatedObjectUndo(go,"Distant station geometry");go.layer=source.gameObject.layer;go.transform.SetParent(source.transform,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;var r=go.AddComponent<MeshRenderer>();r.sharedMaterials=source.sharedMaterials;r.shadowCastingMode=source.shadowCastingMode;var binding=source.GetComponentsInChildren<StationShadowCaster>(true).FirstOrDefault(b=>b.SourceRenderer==source);if(binding){var so=new SerializedObject(binding);r.shadowCastingMode=(ShadowCastingMode)so.FindProperty("originalShadowMode").intValue;}r.receiveShadows=source.receiveShadows;r.lightProbeUsage=source.lightProbeUsage;r.reflectionProbeUsage=source.reflectionProbeUsage;r.probeAnchor=source.probeAnchor?source.probeAnchor:source.transform;r.renderingLayerMask=source.renderingLayerMask;r.motionVectorGenerationMode=source.motionVectorGenerationMode;r.allowOcclusionWhenDynamic=source.allowOcclusionWhenDynamic;var flags=GameObjectUtility.GetStaticEditorFlags(source.gameObject)&~(StaticEditorFlags.OccluderStatic|StaticEditorFlags.BatchingStatic);GameObjectUtility.SetStaticEditorFlags(go,flags);return r;}
 public static object Run(){if(EditorApplication.isPlayingOrWillChangePlaymode||StaticOcclusionCulling.isRunning)throw new Exception("Finish Play/bake first");if(!AssetDatabase.IsValidFolder(Root))AssetDatabase.CreateFolder("Assets/Optimization","StationDistanceLODs");var sources=UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.enabled&&r.shadowCastingMode!=ShadowCastingMode.ShadowsOnly&&r.transform.root.name=="benzinlik"&&!r.GetComponentInParent<LODGroup>()).Select(r=>new{r,m=r.GetComponent<MeshFilter>()?.sharedMesh}).Where(x=>x.m&&x.m.triangles.Length/3>=50000).ToArray();if(sources.Length!=95)throw new Exception("Target set changed; expected95, got"+sources.Length);var meshes=new Dictionary<Mesh,Mesh[]>();foreach(var mesh in sources.Select(x=>x.m).Distinct())meshes.Add(mesh,new[]{Load(mesh,"medium"),Load(mesh,"far")});var scene=EditorSceneManager.GetActiveScene();if(!EditorSceneManager.SaveScene(scene,Work+"/BeforeDistanceLODs.unity",true))throw new Exception("Scene backup failed");string physics=PhysicsSnapshot();var transforms=sources.Select(x=>EditorJsonUtility.ToJson(x.r.transform)).ToArray();Undo.IncrementCurrentGroup();int undo=Undo.GetCurrentGroup();Undo.SetCurrentGroupName("Station distance LODs");var report=new System.Text.StringBuilder();try{foreach(var x in sources){var medium=Child(x.r,meshes[x.m][0],"Station distance LOD1");var far=Child(x.r,meshes[x.m][1],"Station distance LOD2");var high=new List<Renderer>{x.r};high.AddRange(x.r.GetComponentsInChildren<StationShadowCaster>(true).Where(b=>b.SourceRenderer==x.r).Select(b=>(Renderer)b.GetComponent<MeshRenderer>()));var g=Undo.AddComponent<LODGroup>(x.r.gameObject);g.SetLODs(new[]{new LOD(.5f,high.ToArray()),new LOD(.1f,new Renderer[]{medium}),new LOD(.000001f,new Renderer[]{far})});g.RecalculateBounds();float scale=Mathf.Max(Mathf.Abs(g.transform.lossyScale.x),Mathf.Abs(g.transform.lossyScale.y),Mathf.Abs(g.transform.lossyScale.z));float k=g.size*scale*QualitySettings.lodBias/(2*Mathf.Tan(60*Mathf.Deg2Rad*.5f));var levels=g.GetLODs();levels[0].screenRelativeTransitionHeight=Mathf.Clamp(k/40,.00002f,.9f);levels[1].screenRelativeTransitionHeight=Mathf.Min(levels[0].screenRelativeTransitionHeight*.95f,Mathf.Max(.000002f,k/120));levels[2].screenRelativeTransitionHeight=.000001f;g.SetLODs(levels);g.fadeMode=LODFadeMode.CrossFade;g.animateCrossFading=true;EditorUtility.SetDirty(g);report.AppendLine(GlobalObjectId.GetGlobalObjectIdSlow(x.r)+"\t"+x.r.name+"\t"+x.m.triangles.Length/3+"\t"+meshes[x.m][0].triangles.Length/3+"\t"+meshes[x.m][1].triangles.Length/3);}if(physics!=PhysicsSnapshot())throw new Exception("Collider serialization changed");for(int i=0;i<sources.Length;i++)if(transforms[i]!=EditorJsonUtility.ToJson(sources[i].r.transform))throw new Exception("Original transform changed");EditorSceneManager.MarkSceneDirty(scene);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene);Undo.CollapseUndoOperations(undo);File.WriteAllText(Work+"/Installed.tsv",report.ToString());return "Installed95 station LOD groups from24 shared meshes; original geometry to~40m,25% medium to~120m,5% distant. Original transforms and all colliders verified unchanged.";}catch{Undo.RevertAllDownToGroup(undo);throw;}}
}
